from typing import List
from collections import Counter

class Solution:
    def wordSubsets(self, words1: List[str], words2: List[str]) -> List[str]:
        b_max = Counter()
        for b in words2:
            for c, cnt in Counter(b).items():
                b_max[c] = max(b_max[c], cnt)

        ans = []
        for a in words1:
            c_a = Counter(a)
            if all(c_a[c] >= b_max[c] for c in b_max):
                ans.append(a)
        return ans

class Solution {
public:
    vector<string> wordSubsets(vector<string>& words1, vector<string>& words2) {
        vector<int> b_max(26, 0);
        for (string& b : words2) {
            vector<int> cnt(26, 0);
            for (char c : b) cnt[c - 'a']++;
            for (int i = 0; i < 26; i++) b_max[i] = max(b_max[i], cnt[i]);
        }
        vector<string> ans;
        for (string& a : words1) {
            vector<int> cnt(26, 0);
            for (char c : a) cnt[c - 'a']++;
            bool ok = true;
            for (int i = 0; i < 26; i++) {
                if (cnt[i] < b_max[i]) { ok = false; break; }
            }
            if (ok) ans.push_back(a);
        }
        return ans;
    }
};

class Solution {
    public List<String> wordSubsets(String[] words1, String[] words2) {
        int[] bMax = new int[26];
        for (String b : words2) {
            int[] cnt = new int[26];
            for (char c : b.toCharArray()) cnt[c - 'a']++;
            for (int i = 0; i < 26; i++) bMax[i] = Math.max(bMax[i], cnt[i]);
        }
        List<String> ans = new ArrayList<>();
        for (String a : words1) {
            int[] cnt = new int[26];
            for (char c : a.toCharArray()) cnt[c - 'a']++;
            boolean ok = true;
            for (int i = 0; i < 26; i++) {
                if (cnt[i] < bMax[i]) { ok = false; break; }
            }
            if (ok) ans.add(a);
        }
        return ans;
    }
}

var wordSubsets = function(words1, words2) {
    const bMax = new Array(26).fill(0);
    for (const b of words2) {
        const cnt = new Array(26).fill(0);
        for (let i = 0; i < b.length; i++) cnt[b.charCodeAt(i) - 97]++;
        for (let i = 0; i < 26; i++) bMax[i] = Math.max(bMax[i], cnt[i]);
    }
    const ans = [];
    for (const a of words1) {
        const cnt = new Array(26).fill(0);
        for (let i = 0; i < a.length; i++) cnt[a.charCodeAt(i) - 97]++;
        let ok = true;
        for (let i = 0; i < 26; i++) {
            if (cnt[i] < bMax[i]) { ok = false; break; }
        }
        if (ok) ans.push(a);
    }
    return ans;
};
